namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories = new List<RecipeCategory>
        {
            new() { Name = "Breakfast", Description = "Start your day right", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Midday meals and salads", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Hearty evening dishes", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats and baked goods", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Quick bites and appetizers", Icon = "🍿" },
            new() { Name = "Drinks", Description = "Smoothies, cocktails, and more", Icon = "🥤" }
        };

        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Pancakes", Category = "Breakfast", Ingredients = "Flour, Eggs, Milk, Butter, Sugar, Baking powder", Steps = "1. Mix dry ingredients\n2. Whisk wet ingredients\n3. Combine and stir until smooth\n4. Cook on griddle until golden", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Caesar Salad", Category = "Lunch", Ingredients = "Romaine lettuce, Parmesan, Croutons, Caesar dressing, Lemon", Steps = "1. Wash and chop lettuce\n2. Prepare dressing\n3. Toss lettuce with dressing\n4. Top with croutons and parmesan", AverageRating = 4.2, RatingCount = 8 },
            new() { Id = 3, Title = "Spaghetti Carbonara", Category = "Dinner", Ingredients = "Spaghetti, Eggs, Pecorino Romano, Guanciale, Black pepper", Steps = "1. Cook pasta al dente\n2. Fry guanciale until crispy\n3. Mix eggs with cheese\n4. Toss hot pasta with guanciale\n5. Add egg mixture off heat\n6. Season with black pepper", AverageRating = 4.8, RatingCount = 20 },
            new() { Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour", Steps = "1. Melt chocolate and butter\n2. Whisk eggs and sugar\n3. Fold in flour and chocolate mixture\n4. Bake at 425°F for 12 minutes", AverageRating = 4.9, RatingCount = 15 },
            new() { Id = 5, Title = "Guacamole", Category = "Snacks", Ingredients = "Avocados, Lime, Cilantro, Onion, Tomato, Salt", Steps = "1. Mash avocados\n2. Dice onion and tomato\n3. Chop cilantro\n4. Mix all ingredients\n5. Season with lime and salt", AverageRating = 4.6, RatingCount = 10 },
            new() { Id = 6, Title = "Berry Smoothie", Category = "Drinks", Ingredients = "Mixed berries, Banana, Yogurt, Honey, Ice", Steps = "1. Add all ingredients to blender\n2. Blend until smooth\n3. Pour and serve immediately", AverageRating = 4.3, RatingCount = 7 }
        };
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
    }
}

