arguments.file_text:
@page "/category/{CategoryName}"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category yet.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ⭐ @recipe.AverageRating / 5 (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<RecipeHub.Models.Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Services
@inject RecipeService RecipeService

@if (recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeHub</PageTitle>
    <h1>Recipe not found</h1>
    <a href="/" class="btn btn-secondary">← Back to Home</a>
}
else
{
    <PageTitle>@recipe.Title - RecipeHub</PageTitle>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="row mt-4">
        <div class="col-md-6">
            <h3>🧾 Ingredients</h3>
            <ul class="list-group mb-4">
                @foreach (var ingredient in recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>
        <div class="col-md-6">
            <h3>📋 Steps</h3>
            <div class="card">
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n'))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <div class="mt-4 p-3 border rounded">
        <h4>Rate this Recipe</h4>
        <StarRating RecipeId="recipe.Id" CurrentRating="recipe.AverageRating" RatingCount="recipe.RatingCount" />
    </div>

    <a href="/category/@recipe.Category.ToLower()" class="btn btn-secondary mt-3">← Back to @recipe.Category</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="d-inline-block">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= selectedRating ? "selected" : "")"
              style="font-size: 2rem; cursor: pointer;"
              @onclick="() => Rate(star)">
            @(star <= displayRating ? "★" : "☆")
        </span>
    }
    <span class="ms-2 text-muted">@CurrentRating / 5 (@RatingCount ratings)</span>
    @if (hasRated)
    {
        <span class="ms-2 text-success">✓ Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int selectedRating;
    private int displayRating;
    private bool hasRated;

    protected override void OnParametersSet()
    {
        displayRating = (int)Math.Round(CurrentRating);
    }

    private void Rate(int stars)
    {
        if (hasRated) return;

        RecipeService.AddRating(RecipeId, stars);
        selectedRating = stars;
        displayRating = stars;
        hasRated = true;

        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe Submitted!</h4>
        <p>Your recipe "<strong>@model.Title</strong>" has been added to the @model.Category category.</p>
        <a href="/category/@model.Category.ToLower()" class="btn btn-primary">View in Category</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat.Name">@cat.Icon @cat.Name</option>
                }
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="4" @bind-Value="model.Ingredients"
                placeholder="Comma-separated: Flour, Sugar, Butter, Eggs" />
            <div class="form-text">Separate ingredients with commas.</div>
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="model.Steps"
                placeholder="1. Preheat oven to 350°F&#10;2. Mix ingredients&#10;3. Bake for 30 minutes" />
            <div class="form-text">One step per line.</div>
        </div>

        <button type="submit" class="btn btn-success" disabled="@(!IsValid)">Submit Recipe</button>
        <a href="/" class="btn btn-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    private Recipe model = new();
    private bool submitted;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(model.Title) &&
        !string.IsNullOrWhiteSpace(model.Category) &&
        !string.IsNullOrWhiteSpace(model.Ingredients) &&
        !string.IsNullOrWhiteSpace(model.Steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;
        RecipeService.AddRecipe(model);
        submitted = true;
    }

    private void Reset()
    {
        model = new();
        submitted = false;
    }
}

